SELECT 
FROM workspace_memberships wm
JOIN workspaces w ON w.id = wm.workspace_id
WHERE wm.user_id = #{userId}
  AND wm.id = #{membershipId}
  AND w.deleted_at IS NULL

SELECT 
FROM workspace_memberships wm
JOIN workspaces w ON w.id = wm.workspace_id
WHERE wm.user_id = #{userId}
  AND wm.workspace_id = #{workspaceId}
  AND w.deleted_at IS NULL
